import re

with open('docs/paper/references.bib') as f:
    content = f.read()

# Better parsing: handle nested braces
def extract_brace_content(s, start):
    '''Extract content between matching braces starting at position start'''
    depth = 0
    for i in range(start, len(s)):
        if s[i] == '{':
            depth += 1
        elif s[i] == '}':
            depth -= 1
            if depth == 0:
                return s[start+1:i], i
    return None, len(s)

# Parse entries
entries = []
for m in re.finditer(r'@(\w+)\{([^,]+),', content):
    etype = m.group(1)
    key = m.group(2)
    pos = m.end()

    # Find all fields in this entry
    fields = {}
    field_pattern = re.compile(r'(\w+)\s*=\s*\{')
    remaining = content[pos:]
    for fm in field_pattern.finditer(remaining):
        fname = fm.group(1).lower()
        val, end = extract_brace_content(remaining, fm.start() + len(fm.group(0)) - 1)
        if val is not None:
            fields[fname] = val

    entries.append((etype, key, fields))

format_issues = []
proper_nouns = ['BERT', 'GPT', 'LLM', 'LLMs', 'NLP', 'AI', 'DeepSeek', 'QwQ', 'LEACE', 'BERTology']

for etype, key, fields in entries:
    title = fields.get('title', '')

    for noun in proper_nouns:
        if noun not in title:
            continue

        # Check if every occurrence of noun is inside braces
        # Find all positions of noun
        idx = 0
        while True:
            pos = title.find(noun, idx)
            if pos == -1:
                break

            # Check brace depth at this position
            depth = 0
            for i in range(pos):
                if title[i] == '{':
                    depth += 1
                elif title[i] == '}':
                    depth -= 1

            if depth == 0:
                format_issues.append(f'  - \`{key}\`: \"{noun}\" in title not brace-protected')
                break
            idx = pos + len(noun)

# Check 'and others'
for etype, key, fields in entries:
    author = fields.get('author', '')
    if 'and others' in author.lower():
        format_issues.append(f'  - \`{key}\`: author contains \"and others\"')

print('=== FORMAT ISSUES (verified) ===')
if format_issues:
    for i in format_issues:
        print(i)
else:
    print('none')
